    }
  ]
  ,
  "extras": [
    {
      "after_item": "S5_MEDIA",
      "title_raw": "가. 적절한(및 부적절한) 소화제",
      "reason": "코드없음",
      "statements": [
        {
          "key": "이 물질과 관련된 소화 시",
          "value": "알코올 포말, 이산화탄소 또는 물 분무를 사용할 것"
        ,
        "line": "p3:L11"
        },
        {
          "key": "질식소화 시",
          "value": "건조한 모래 또는 흙을 사용할 것"
        ,
        "line": "p3:L12"
        }
      ]
    ,
    "suggested_code": "S5_MEDIA"
    ,
    "line": "p3:L10"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw": "나. 화학물질로부터 생기는 특정 유해성",
      "reason": "코드없음",
      "statements": [
        {
          "key": "공기와",
          "value": "폭발성 혼합물을 형성함"
        ,
        "line": "p3:L14"
        },
        {
          "value": "극인화성 가스"
        ,
        "line": "p3:L15"
        },
        {
          "key": "열, 스파크, 화염에 의해",
          "value": "쉽게 점화함"
        ,
        "line": "p3:L16"
        },
        {
          "key": "현기증 또는 질식을",
          "value": "유발할 수 있음"
        ,
        "line": "p3:L17"
        },
        {
          "key": "점화원까지 이동하여",
          "value": "역화(flash back)할 수 있음"
        ,
        "line": "p3:L18"
        }
      ]
    ,
    "suggested_code": "S5_SPECIFIC"
    ,
    "line": "p3:L13"
    },
    {
      "after_item": "S5_FIREFIGHT",
      "title_raw": "다. 화재진압 시 착용할 보호구 및 예방조치",
      "reason": "코드없음",
      "statements": [
        {
          "key": "누출성 가스 화재 시",
          "value": "누출을 안전하게 막을 수 없다면 불을 끄려하지 마시오."
        ,
        "line": "p3:L20"
        },
        {
          "key": "누출이 중지되지 않는다면",
          "value": "누출가스화재를 소화하지 마시오."
        ,
        "line": "p3:L21"
        },
        {
          "key": "안전하게 처리하는 것이 가능하면",
          "value": "모든 점화원을 제거하시오."
        ,
        "line": "p3:L22"
        },
        {
          "key": "위험하지 않다면",
          "value": "화재지역에서 용기를 옮기시오."
        ,
        "line": "p3:L23"
        },
        {
          "key": "지역을 벗어나 안전거리를 유지하여",
          "value": "소화하시오."
        ,
        "line": "p3:L24"
        },
        {
          "key": "탱크 화재 시 결빙될 수 있으므로 노출원 또는 안전장치에",
          "value": "직접 주수하지 마시오."
        ,
        "line": "p3:L25"
        },
        {
          "key": "탱크 화재 시 대규모 화재의 경우",
          "value": "무인 소화장비를 이용하고 불가능하다면 물러나 타게 놔두시오."
        ,
        "line": "p3:L26"
        },
        {
          "key": "탱크 화재 시 소화가 진화된 후에도",
          "value": "다량의 물로 용기를 식히시오."
        ,
        "line": "p3:L28"
        },
        {
          "key": "탱크 화재 시 압력 방출장치에서 고음이 있거나 탱크가 변색할 경우",
          "value": "즉시 물러나시오."
        ,
        "line": "p3:L29"
        },
        {
          "key": "탱크 화재 시",
          "value": "최대거리에서 소화하거나 무인 소화장비를 이용하시오."
        ,
        "line": "p3:L30"
        },
        {
          "key": "탱크 화재 시 화염에 휩싸인 탱크에서",
          "value": "물러나시오."
        ,
        "line": "p3:L31"
        },
        {
          "key": "파손된 실린더는",
          "value": "날아오를 수 있음."
        ,
        "line": "p3:L32"
        }
      ]
    ,
    "suggested_code": "S5_FIREFIGHT"
    ,
    "line": "p3:L19"
    }
  ]
}

